    #[test]
    fn unsupported_primary_sources_retain_exact_evidence_and_reason() {
        let fixture = TempDir::new().expect("fixture root exists");
        let sources = [
            (
                "Session.m",
                "@interface Session : NSObject\n@end\n",
                "objective-c",
            ),
            (
                "classify.m",
                "function result = classify(value)\nresult = value;\nend\n",
                "matlab",
            ),
            ("script.pl", "sub render { return 1; }\n", "perl"),
            (
                "mystery.sourceblob",
                "opaqueWidget configures lexicalFallback\n",
                "unknown",
            ),
        ];
        for (path, content, _) in sources {
            fs::write(fixture.path().join(path), content).expect("source fixture writes");
        }
        let mut service = FirstSliceService::new(2).expect("service initializes");
        let receipt = service
            .index_repository(fixture.path(), &deadline())
            .expect("unsupported sources publish");
        let generation = service
            .loaded_generation_snapshot(receipt.generation)
            .expect("published generation remains retained");

        for (path, content, language) in sources {
            let file = generation
                .document()
                .files
                .iter()
                .find(|file| file.path == path)
                .expect("unsupported file remains represented");
            let coverage = service
                .source_file_coverage_until(receipt.generation, file.id, &deadline())
                .expect("source coverage resolves");
            assert_eq!(coverage.language, language);
            assert_eq!(coverage.tier, AnalysisTier::TierD);
            assert_eq!(coverage.status, CoverageStatus::Unknown);
            assert_eq!(
                coverage.reason,
                Some(FirstSliceSourceCoverageReason::UnsupportedLanguage)
            );
            let reference = file
                .evidence
                .source
                .clone()
                .expect("unsupported file carries source evidence");
            let read = service
                .source_read(receipt.generation, vec![reference.clone()], &deadline())
                .expect("unsupported source remains readable");
            assert_eq!(read.data.chunks[0].bytes, content.as_bytes());
            assert_eq!(read.data.chunks[0].language, language);
            let exact_identifier = content
                .split(|character: char| !(character == '_' || character.is_alphanumeric()))
                .find(|candidate| {
                    candidate.len() > 4
                        && candidate
                            .chars()
                            .next()
                            .is_some_and(|character| character.is_alphabetic())
                })
                .expect("fixture contains a searchable identifier");
            for (query, mode) in [
                (exact_identifier.to_owned(), LocateMode::Exact),
                (exact_identifier.to_owned(), LocateMode::Text),
                (path.to_owned(), LocateMode::Prefix),
            ] {
                let located = service
                    .code_locate(receipt.generation, query, mode, 10, 0, &deadline())
                    .expect("unsupported source locates");
                let hit = located
                    .data
                    .hits
                    .iter()
                    .find(|hit| hit.file == file.id)
                    .expect("file-only source hit is returned");
                assert_eq!(hit.symbol, None);
                assert_eq!(hit.kind, "file");
                assert_eq!(hit.source.as_ref(), Some(&reference));
            }
        }
        let gaps = service
            .coverage_gaps_until(receipt.repository, receipt.generation, &deadline())
            .expect("coverage gaps resolve");
        assert!(gaps.iter().any(|gap| {
            gap.reason == FirstSliceCoverageGapReason::Unrecognized
                && gap.language.as_deref() == Some("unknown")
                && gap.files == 1
        }));
        for language in ["objective-c", "matlab", "perl"] {
            assert!(gaps.iter().any(|gap| {
                gap.reason == FirstSliceCoverageGapReason::Unsupported
                    && gap.language.as_deref() == Some(language)
                    && gap.files == 1
            }));
        }
    }

    #[test]
    fn ruby_published_declarations_preserve_symbols_and_exact_source() {
        let fixture = TempDir::new().expect("fixture root exists");
        let source = "module Garden\n class Store\n  DEFAULT = 1\n  def lookup(key)\n   key\n  end\n  def self.lookup(key)\n   new(key)\n  end\n  def [](key)\n   key\n  end\n  def ready\n   true\n  end\n  def self.build\n   new\n  end\n  def version = 1\n end\nend\n";
        fs::write(fixture.path().join("store.rb"), source).expect("Ruby source writes");
        let mut service = FirstSliceService::new(2).expect("service initializes");
        let receipt = service
            .index_repository(fixture.path(), &deadline())
            .expect("Ruby index publishes");
        let generation = service
            .loaded_generation_snapshot(receipt.generation)
            .expect("generation remains retained");
        assert!(generation.document().diagnostics.is_empty());
        let file = generation
            .document()
            .files
            .iter()
            .find(|file| file.path == "store.rb")
            .expect("Ruby source file remains represented");
        let coverage = service
            .source_file_coverage_until(receipt.generation, file.id, &deadline())
            .expect("Ruby file coverage resolves");
        assert_eq!(coverage.language, "ruby");
        assert_eq!(coverage.tier, AnalysisTier::TierD);
        assert_eq!(
            coverage.status,
            CoverageStatus::Complete,
            "{:?}",
            generation.document().skipped_regions
        );
        assert_eq!(coverage.reason, None);
        let source_read = service
            .source_read(
                receipt.generation,
                vec![file.evidence.source.clone().expect("Ruby file has source")],
                &deadline(),
            )
            .expect("complete Ruby source reads");
        assert_eq!(source_read.data.chunks[0].bytes, source.as_bytes());
        assert_eq!(source_read.data.chunks[0].language, "ruby");
        let status = service
            .repository_status(receipt.repository, None)
            .expect("Ruby repository status resolves");
        let indexed = status
            .coverage
            .iter()
            .find(|entry| entry.language == "ruby")
            .expect("Ruby indexing is accounted");
        assert_eq!((indexed.discovered_files, indexed.indexed_files), (1, 1));
        for name in [
            "Garden",
            "Store",
            "DEFAULT",
            "lookup",
            "self.lookup",
            "[]",
            "ready",
            "self.build",
            "version",
        ] {
            let located = service
                .code_locate(
                    receipt.generation,
                    name.to_owned(),
                    LocateMode::Exact,
                    10,
                    0,
                    &deadline(),
                )
                .expect("Ruby symbol locates");
            let hit = located
                .data
                .hits
                .iter()
                .find(|hit| hit.symbol.is_some())
                .expect("Ruby declaration has a symbol identity");
            let explained = service
                .symbol_explain(
                    receipt.generation,
                    hit.symbol.expect("symbol exists"),
                    &deadline(),
                )
                .expect("Ruby symbol explains");
            assert_eq!(explained.data.entity.language, "ruby");
            assert_eq!(explained.data.entity.canonical_name, name);
            let reference = explained
                .data
                .entity
                .evidence
                .source
                .expect("symbol source exists");
            assert_eq!(reference.generation(), receipt.generation);
            let start =
                usize::try_from(reference.span().start_byte()).expect("fixture offset fits");
            let end = usize::try_from(reference.span().end_byte()).expect("fixture offset fits");
            let read = service
                .source_read_with_options_and_budget(
                    receipt.generation,
                    vec![reference],
                    SourceReadOptions::new()
                        .with_context_lines_before(0)
                        .with_context_lines_after(0),
                    FirstSliceBudget::default(),
                    &deadline(),
                )
                .expect("Ruby source reads");
            assert_eq!(
                read.data.chunks[0].bytes,
                source
                    .as_bytes()
                    .get(start..end)
                    .expect("source range exists")
            );
        }
        let inventory = service
            .support_inventory_snapshot()
            .expect("capabilities resolve");
        let capability = inventory
            .languages
            .iter()
            .find(|entry| entry.language == "ruby")
            .expect("Ruby capability exists");
        assert_eq!(capability.maximum_tier, "tier_d");
        assert_eq!(capability.analyzers, ["treesitter"]);
    }

    #[test]
    fn css_repeated_definitions_survive_locate_explain_and_durable_restore() {
        let storage = durable_test_tempdir();
        let paths = RuntimePaths::new(storage.path().join("state"), storage.path().join("runtime"))
            .expect("runtime paths are valid");
        paths.prepare_owner().expect("private paths prepare");
        let fixture = durable_test_tempdir();
        let source = concat!(
            ".card { --accent: red; }\n",
            ".card { --accent: blue; }\n",
            "@media print { .card { --accent: black; } }\n",
            "@media print { .card { --accent: gray; } }\n",
        );
        let path = fixture.path().join("theme.css");
        fs::write(&path, source).expect("stylesheet writes");
        let mut service = FirstSliceService::new_durable(3, paths.state_dir(), &deadline())
            .expect("service initializes");
        let initial = service
            .index_repository(fixture.path(), &deadline())
            .expect("CSS publishes");
        let no_op = service
            .index_repository(fixture.path(), &deadline())
            .expect("CSS no-op publishes");
        assert_eq!(no_op.generation, initial.generation);
        let changed = format!(
            ".unrelated {{ color: pink; }}\n{}",
            source.replace("gray", "silver")
        );
        fs::write(&path, &changed).expect("body and sibling edit writes");
        let updated = service
            .index_repository(fixture.path(), &deadline())
            .expect("CSS edit publishes");
        assert_ne!(updated.generation, initial.generation);
        drop(service);
        let restored = FirstSliceService::new_durable(3, paths.state_dir(), &deadline())
            .expect("both generations restore");
        let mut initial_symbols = None;
        for (receipt, expected_source) in [(&initial, source), (&updated, changed.as_str())] {
            let located = restored
                .code_locate(
                    receipt.generation,
                    "--accent".to_owned(),
                    LocateMode::Exact,
                    10,
                    0,
                    &deadline(),
                )
                .expect("both contexts locate");
            assert!(!located.data.truncated);
            let symbols = located
                .data
                .hits
                .iter()
                .filter_map(|hit| hit.symbol)
                .collect::<BTreeSet<_>>();
            assert_eq!(symbols.len(), 2);
            if let Some(previous) = &initial_symbols {
                assert_eq!(previous, &symbols);
            } else {
                initial_symbols = Some(symbols.clone());
            }
            let mut declarations = BTreeSet::new();
            for symbol in symbols {
                let explained = restored
                    .symbol_explain(receipt.generation, symbol, &deadline())
                    .expect("context group explains");
                assert!(!explained.data.truncated);
                let definitions = explained
                    .data
                    .occurrences
                    .iter()
                    .filter(|occurrence| {
                        occurrence.role == OccurrenceRole::Definition
                            && occurrence.target == OccurrenceTarget::Resolved { symbol }
                    })
                    .collect::<Vec<_>>();
                assert_eq!(definitions.len(), 2);
                for definition in definitions {
                    assert_eq!(definition.source.generation(), receipt.generation);
                    assert_eq!(definition.syntactic_text_hash, content_hash(b"--accent"));
                    assert_eq!(
                        definition.source.content_hash(),
                        content_hash(expected_source.as_bytes())
                    );
                    let read = restored
                        .source_read_with_options_and_budget(
                            receipt.generation,
                            vec![
                                definition.source.clone(),
                                definition
                                    .evidence
                                    .source
                                    .clone()
                                    .expect("full declaration context"),
                            ],
                            SourceReadOptions::new()
                                .with_context_lines_before(0)
                                .with_context_lines_after(0),
                            FirstSliceBudget::default(),
                            &deadline(),
                        )
                        .expect("every declaration reads");
                    assert_eq!(read.data.chunks.len(), 2);
                    assert!(
                        read.data
                            .chunks
                            .iter()
                            .any(|chunk| chunk.bytes == b"--accent")
                    );
                    let declaration = read
                        .data
                        .chunks
                        .iter()
                        .find(|chunk| chunk.bytes.starts_with(b"--accent:"))
                        .expect("full declaration is preserved");
                    declarations.insert(
                        String::from_utf8(declaration.bytes.clone()).expect("CSS is UTF-8"),
                    );
                }
            }
            let final_value = if receipt.generation == initial.generation {
                "gray"
            } else {
                "silver"
            };
            let expected = ["red", "blue", "black", final_value]
                .into_iter()
                .map(|value| format!("--accent: {value};"))
                .collect::<BTreeSet<_>>();
            assert_eq!(declarations, expected);
        }
    }

    #[test]
    fn bash_published_symbols_and_sources_survive_edits_and_restore() {
        let storage = durable_test_tempdir();
        let paths = RuntimePaths::new(storage.path().join("state"), storage.path().join("runtime"))
            .expect("runtime paths");
        paths.prepare_owner().expect("private runtime");
        let fixture = durable_test_tempdir();
        let source =
            include_str!("../../rootlight-adapter-treesitter/tests/fixtures/structural/bash.sh");
        let path = fixture.path().join("commands.sh");
        fs::write(&path, source).expect("Bash fixture");
        fs::write(
            fixture.path().join("helper"),
            "#!/usr/bin/env bash\nhelper() { :; }\n",
        )
        .expect("shebang fixture");
        let mut service =
            FirstSliceService::new_durable(3, paths.state_dir(), &deadline()).expect("service");
        let support = service.support_inventory_snapshot().expect("support");
        let bash = support
            .languages
            .iter()
            .find(|entry| entry.language == "bash")
            .expect("Bash capability");
        assert_eq!(bash.maximum_tier, "tier_d");
        assert_eq!(bash.analyzers, ["treesitter"]);
        let initial = service
            .index_repository(fixture.path(), &deadline())
            .expect("index");
        let status = service
            .repository_status(initial.repository, None)
            .expect("status");
        let coverage = status
            .coverage
            .iter()
            .find(|entry| entry.language == "bash")
            .expect("Bash coverage");
        assert_eq!((coverage.discovered_files, coverage.indexed_files), (2, 2));
        let generation = service
            .loaded_generation_snapshot(initial.generation)
            .expect("generation");
        let file = generation
            .document()
            .files
            .iter()
            .find(|file| file.path == "commands.sh")
            .expect("file");
        let full_ref = file.evidence.source.clone().expect("file source");
        let read = service
            .source_read(initial.generation, vec![full_ref.clone()], &deadline())
            .expect("full source");
        assert_eq!(read.data.chunks[0].bytes, source.as_bytes());
        let mut symbols = BTreeMap::new();
        for name in [
            "emit", "process", "render", "ROOT", "ITEMS", "message", "pending", "item", "helper",
        ] {
            let located = service
                .code_locate(
                    initial.generation,
                    name.to_owned(),
                    LocateMode::Exact,
                    20,
                    0,
                    &deadline(),
                )
                .expect("locate");
            let hit = located
                .data
                .hits
                .iter()
                .find(|hit| hit.symbol.is_some())
                .expect("symbol hit");
            let symbol = hit.symbol.expect("symbol");
            let explained = service
                .symbol_explain(initial.generation, symbol, &deadline())
                .expect("explain");
            assert_eq!(explained.data.entity.canonical_name, name);
            assert_eq!(explained.data.entity.language, "bash");
            let reference = explained
                .data
                .entity
                .evidence
                .source
                .expect("declaration source");
            assert_eq!(reference.generation(), initial.generation);
            if name != "helper" {
                let start = usize::try_from(reference.span().start_byte()).expect("start");
                let end = usize::try_from(reference.span().end_byte()).expect("end");
                let read = service
                    .source_read_with_options_and_budget(
                        initial.generation,
                        vec![reference],
                        SourceReadOptions::new()
                            .with_context_lines_before(0)
                            .with_context_lines_after(0),
                        FirstSliceBudget::default(),
                        &deadline(),
                    )
                    .expect("exact source");
                assert_eq!(read.data.chunks[0].bytes, &source.as_bytes()[start..end]);
            }
            symbols.insert(name, symbol);
        }
        let no_op = service
            .index_repository(fixture.path(), &deadline())
            .expect("no-op");
        assert_eq!(no_op.generation, initial.generation);
        let changed = source.replace("first $ROOT", "changed $ROOT");
        fs::write(&path, &changed).expect("body edit");
        let updated = service
            .index_repository(fixture.path(), &deadline())
            .expect("incremental index");
        assert_ne!(updated.generation, initial.generation);
        drop(generation);
        drop(service);
        let restored =
            FirstSliceService::new_durable(3, paths.state_dir(), &deadline()).expect("restore");
        let old_read = restored
            .source_read(initial.generation, vec![full_ref], &deadline())
            .expect("historical source");
        assert_eq!(old_read.data.chunks[0].bytes, source.as_bytes());
        for receipt in [&initial, &updated] {
            let generation = restored
                .loaded_generation_snapshot(receipt.generation)
                .expect("retained generation");
            let file = generation
                .document()
                .files
                .iter()
                .find(|file| file.path == "commands.sh")
                .expect("retained file");
            let reference = file.evidence.source.clone().expect("retained full source");
            let read = restored
                .source_read(receipt.generation, vec![reference], &deadline())
                .expect("retained source read");
            let expected = if receipt.generation == initial.generation {
                source
            } else {
                &changed
            };
            assert_eq!(read.data.chunks[0].bytes, expected.as_bytes());
            for (name, symbol) in &symbols {
                let explained = restored
                    .symbol_explain(receipt.generation, *symbol, &deadline())
                    .expect("restored identity");
                assert_eq!(explained.data.entity.canonical_name, *name);
                assert_eq!(
                    explained
                        .data
                        .entity
                        .evidence
                        .source
                        .expect("source")
                        .generation(),
                    receipt.generation
                );
            }
        }
    }

