    #[test]
    fn yaml_collection_keys_survive_durable_query_and_source_reads() {
        let storage = durable_test_tempdir();
        let paths = RuntimePaths::new(storage.path().join("state"), storage.path().join("runtime"))
            .expect("paths");
        paths.prepare_owner().expect("runtime");
        let fixture = durable_test_tempdir();
        let source = "base: &key [one, {a: 1}]\n? *key\n: first\n";
        let edited = source.replace(": first", ": second");
        let path = fixture.path().join("data.yaml");
        fs::write(&path, source).expect("fixture");
        let mut service =
            FirstSliceService::new_durable(3, paths.state_dir(), &deadline()).expect("service");
        let first = service
            .index_repository(fixture.path(), &deadline())
            .expect("index");
        let noop = service
            .index_repository(fixture.path(), &deadline())
            .expect("no-op");
        assert_eq!(first.generation, noop.generation);
        fs::write(&path, &edited).expect("edit");
        let second = service
            .index_repository(fixture.path(), &deadline())
            .expect("incremental");
        assert_ne!(first.generation, second.generation);
        drop(service);
        let service =
            FirstSliceService::new_durable(3, paths.state_dir(), &deadline()).expect("restore");
        let mut previous = None;
        for receipt in [&first, &second] {
            let generation = service
                .loaded_generation_snapshot(receipt.generation)
                .expect("generation");
            let document = generation.document();
            assert!(document.diagnostics.is_empty());
            assert!(
                document.skipped_regions.is_empty(),
                "{:?}",
                document.skipped_regions
            );
            let entity = document
                .entities
                .iter()
                .find(|entity| {
                    entity.kind == EntityKind::Property && entity.canonical_name.starts_with("seq:")
                })
                .expect("collection key");
            if let Some(previous) = previous {
                assert_eq!(entity.id, previous);
            }
            previous = Some(entity.id);
            let located = service
                .code_locate(
                    receipt.generation,
                    entity.display_name.clone(),
                    LocateMode::Exact,
                    20,
                    0,
                    &deadline(),
                )
                .expect("locate");
            assert!(
                located
                    .data
                    .hits
                    .iter()
                    .any(|hit| hit.symbol == Some(entity.id))
            );
            let explained = service
                .symbol_explain(receipt.generation, entity.id, &deadline())
                .expect("explain");
            assert_eq!(explained.data.entity.canonical_name, entity.canonical_name);
            let definition = document
                .occurrences
                .iter()
                .find(|occurrence| {
                    occurrence.role == OccurrenceRole::Definition
                        && occurrence.target == (OccurrenceTarget::Resolved { symbol: entity.id })
                })
                .expect("definition");
            let read = service
                .source_read_with_options_and_budget(
                    receipt.generation,
                    vec![definition.source.clone()],
                    SourceReadOptions::new()
                        .with_context_lines_before(0)
                        .with_context_lines_after(0),
                    FirstSliceBudget::default(),
                    &deadline(),
                )
                .expect("source");
            assert_eq!(read.data.chunks[0].bytes, b"*key");
            assert_eq!(definition.source.generation(), receipt.generation);
        }
    }

    fn data_properties_survive_durable_restore(
        language: &str,
        relative: &str,
        source: &str,
        edit: [&str; 2],
    ) {
        let storage = durable_test_tempdir();
        let paths = RuntimePaths::new(storage.path().join("state"), storage.path().join("runtime"))
            .expect("paths");
        paths.prepare_owner().expect("private runtime");
        let fixture = durable_test_tempdir();
        let path = fixture.path().join(relative);
        fs::write(&path, source).expect("data fixture");
        let mut service =
            FirstSliceService::new_durable(3, paths.state_dir(), &deadline()).expect("service");
        let support = service.support_inventory_snapshot().expect("support");
        let capability = support
            .languages
            .iter()
            .find(|entry| entry.language == language)
            .expect("data capability");
        assert_eq!(capability.maximum_tier, "tier_d");
        assert_eq!(capability.analyzers, ["treesitter"]);
        let initial = service
            .index_repository(fixture.path(), &deadline())
            .expect("index");
        let no_op = service
            .index_repository(fixture.path(), &deadline())
            .expect("no-op");
        assert_eq!(initial.generation, no_op.generation);
        let edited = source.replace(edit[0], edit[1]);
        fs::write(&path, &edited).expect("value edit");
        let updated = service
            .index_repository(fixture.path(), &deadline())
            .expect("incremental");
        assert_ne!(initial.generation, updated.generation);
        drop(service);
        let service =
            FirstSliceService::new_durable(3, paths.state_dir(), &deadline()).expect("restore");
        let mut previous = None;
        for (receipt, source) in [(&initial, source), (&updated, edited.as_str())] {
            let generation = service
                .loaded_generation_snapshot(receipt.generation)
                .expect("generation");
            let document = generation.document();
            if language == "yaml" {
                let anchors: Vec<_> = document
                    .entities
                    .iter()
                    .filter(|entity| {
                        entity.kind == EntityKind::Variable && entity.canonical_name == "entry"
                    })
                    .collect();
                assert_eq!(anchors.len(), 1);
                let aliases: Vec<_> = document
                    .occurrences
                    .iter()
                    .filter(|occurrence| occurrence.syntax_kind == "yaml.alias.reference")
                    .collect();
                assert_eq!(aliases.len(), 1);
                assert_eq!(
                    aliases[0].target,
                    OccurrenceTarget::Resolved {
                        symbol: anchors[0].id
                    }
                );
                assert_eq!(aliases[0].source.generation(), receipt.generation);
            }
            assert_eq!(
                document
                    .entities
                    .iter()
                    .filter(|entity| entity.kind == EntityKind::Property)
                    .count(),
                7
            );
            let file = document
                .files
                .iter()
                .find(|file| file.path == relative)
                .expect("file");
            let full = service
                .source_read(
                    receipt.generation,
                    vec![file.evidence.source.clone().expect("full source")],
                    &deadline(),
                )
                .expect("whole source");
            assert_eq!(full.data.chunks[0].bytes, source.as_bytes());
            let located = service
                .code_locate(
                    receipt.generation,
                    "key".to_owned(),
                    LocateMode::Exact,
                    20,
                    0,
                    &deadline(),
                )
                .expect("decoded exact locate");
            let symbols: BTreeSet<_> = located
                .data
                .hits
                .iter()
                .filter_map(|hit| hit.symbol)
                .collect();
            assert_eq!(symbols.len(), 4);
            for symbol in &symbols {
                let explained = service
                    .symbol_explain(receipt.generation, *symbol, &deadline())
                    .expect("explain");
                assert_eq!(
                    explained.data.entity.canonical_name,
                    if language == "yaml" {
                        r#"str:"key""#
                    } else {
                        r#""key""#
                    }
                );
                assert_eq!(explained.data.entity.display_name, "key");
                let occurrence = document
                    .occurrences
                    .iter()
                    .find(|occurrence| {
                        occurrence.role == OccurrenceRole::Definition
                            && occurrence.target == (OccurrenceTarget::Resolved { symbol: *symbol })
                    })
                    .expect("definition");
                let name_ref = occurrence.source.clone();
                let declaration_ref = occurrence
                    .evidence
                    .source
                    .clone()
                    .expect("full declaration");
                let read = service
                    .source_read_with_options_and_budget(
                        receipt.generation,
                        vec![name_ref.clone(), declaration_ref.clone()],
                        SourceReadOptions::new()
                            .with_context_lines_before(0)
                            .with_context_lines_after(0),
                        FirstSliceBudget::default(),
                        &deadline(),
                    )
                    .expect("exact source");
                for reference in [name_ref, declaration_ref] {
                    assert_eq!(reference.generation(), receipt.generation);
                    let start = usize::try_from(reference.span().start_byte()).expect("start");
                    let end = usize::try_from(reference.span().end_byte()).expect("end");
                    assert!(
                        read.data
                            .chunks
                            .iter()
                            .any(|chunk| chunk.bytes == source.as_bytes()[start..end])
                    );
                }
            }
            if let Some(previous) = previous {
                assert_eq!(symbols, previous);
            }
            previous = Some(symbols);
        }
    }

    #[test]
    fn html_sources_and_markup_survive_incremental_publication_and_restart() {
        let storage = durable_test_tempdir();
        let paths = RuntimePaths::new(storage.path().join("state"), storage.path().join("runtime"))
            .expect("runtime paths are valid");
        paths.prepare_owner().expect("private paths prepare");
        let fixture = durable_test_tempdir();
        let source = "<main><item key='one' key='two'>first</item><item key='three'>second</item><script>const embedded = '<fake />';</script></main>\n";
        let context =
            "<svg><title><b>foreign</b></title></svg><noscript><b>conditional</b></noscript>";
        fs::write(fixture.path().join("view.html"), source).unwrap();
        fs::write(fixture.path().join("context.HTM"), context).unwrap();
        fs::write(
            fixture.path().join("companion.rs"),
            "pub fn companion() {}\n",
        )
        .unwrap();
        let mut service =
            FirstSliceService::new_durable(3, paths.state_dir(), &deadline()).unwrap();
        let initial = service
            .index_repository(fixture.path(), &deadline())
            .unwrap();
        assert_eq!(initial.indexed_files, 3);
        let status = service.repository_status(initial.repository, None).unwrap();
        let coverage = status
            .coverage
            .iter()
            .find(|row| row.language == "html")
            .unwrap();
        assert_eq!((coverage.discovered_files, coverage.indexed_files), (2, 2));
        assert_eq!(coverage.tier, "tier_d");
        assert_ne!(coverage.status, "complete");
        let original = service
            .loaded_generation_snapshot(initial.generation)
            .unwrap();
        let identities = original
            .document()
            .entities
            .iter()
            .filter(|entity| entity.language == "html")
            .map(|entity| (entity.id, (entity.kind, entity.canonical_name.clone())))
            .collect::<BTreeMap<_, _>>();
        assert!(!identities.values().any(|(_, name)| name == "fake"));
        for detail in [
            "html-dom-semantics-unavailable",
            "html-embedded-analysis-unavailable",
            "html-foreign-context-unavailable",
            "html-scripting-mode-unavailable",
        ] {
            assert!(
                original
                    .document()
                    .skipped_regions
                    .iter()
                    .any(|gap| gap.detail == detail)
            );
        }
        let no_op = service
            .index_repository(fixture.path(), &deadline())
            .unwrap();
        assert_eq!(no_op.generation, initial.generation);
        let changed = source.replace("second", "updated source text");
        fs::write(fixture.path().join("view.html"), &changed).unwrap();
        let updated = service
            .index_repository(fixture.path(), &deadline())
            .unwrap();
        assert_ne!(updated.generation, initial.generation);
        drop(original);
        drop(service);
        let restored = FirstSliceService::new_durable(3, paths.state_dir(), &deadline()).unwrap();
        for (receipt, expected_source) in [(&initial, source), (&updated, changed.as_str())] {
            let generation = restored
                .loaded_generation_snapshot(receipt.generation)
                .unwrap();
            let document = generation.document();
            assert_eq!(document.version, NormalizedIrVersion::V1_3);
            assert_eq!(document.files.len(), 3);
            assert_eq!(
                document
                    .entities
                    .iter()
                    .filter(|entity| entity.language == "html")
                    .map(|entity| (entity.id, (entity.kind, entity.canonical_name.clone())))
                    .collect::<BTreeMap<_, _>>(),
                identities
            );
            for (path, expected) in [("view.html", expected_source), ("context.HTM", context)] {
                let file = document
                    .files
                    .iter()
                    .find(|file| file.path == path)
                    .unwrap();
                let reference = file.evidence.source.clone().unwrap();
                assert_eq!(reference.generation(), receipt.generation);
                let read = restored
                    .source_read(receipt.generation, vec![reference], &deadline())
                    .unwrap();
                assert_eq!(read.data.chunks[0].bytes, expected.as_bytes());
                assert_eq!(read.data.chunks[0].language, "html");
            }
            for (name, kind, count) in [
                ("item", EntityKind::MarkupElement, 2),
                ("key", EntityKind::MarkupAttribute, 3),
            ] {
                let located = restored
                    .code_locate(
                        receipt.generation,
                        name.to_owned(),
                        LocateMode::Exact,
                        10,
                        0,
                        &deadline(),
                    )
                    .unwrap();
                let symbols = located
                    .data
                    .hits
                    .iter()
                    .filter_map(|hit| hit.symbol)
                    .collect::<BTreeSet<_>>();
                assert_eq!(symbols.len(), count);
                for symbol in symbols {
                    let explained = restored
                        .symbol_explain(receipt.generation, symbol, &deadline())
                        .unwrap();
                    assert_eq!(explained.data.entity.kind, kind);
                    let reference = explained.data.entity.evidence.source.unwrap();
                    assert_eq!(reference.generation(), receipt.generation);
                    let start = usize::try_from(reference.span().start_byte()).unwrap();
                    let end = usize::try_from(reference.span().end_byte()).unwrap();
                    let read = restored
                        .source_read_with_options_and_budget(
                            receipt.generation,
                            vec![reference],
                            SourceReadOptions::new()
                                .with_context_lines_before(0)
                                .with_context_lines_after(0),
                            FirstSliceBudget::default(),
                            &deadline(),
                        )
                        .unwrap();
                    assert_eq!(
                        read.data.chunks[0].bytes,
                        expected_source.as_bytes()[start..end]
                    );
                }
            }
        }
    }

    #[test]
    fn sql_source_declarations_survive_incremental_publication_and_restart() {
        let storage = durable_test_tempdir();
        let paths = RuntimePaths::new(storage.path().join("state"), storage.path().join("runtime"))
            .unwrap();
        paths.prepare_owner().unwrap();
        let fixture = durable_test_tempdir();
        let source = "CREATE TABLE app.account(id INT);\nCREATE TABLE app.account(id TEXT);\nCREATE VIEW app.active AS SELECT id FROM app.account;\nCREATE FUNCTION app.identity(value INT) RETURNS INT AS $$ SELECT value; $$ LANGUAGE SQL;\n";
        fs::write(fixture.path().join("schema.sql"), source).unwrap();
        let mut service =
            FirstSliceService::new_durable(3, paths.state_dir(), &deadline()).unwrap();
        let initial = service
            .index_repository(fixture.path(), &deadline())
            .unwrap();
        assert_eq!(initial.indexed_files, 1);
        let status = service.repository_status(initial.repository, None).unwrap();
        let coverage = status
            .coverage
            .iter()
            .find(|row| row.language == "sql")
            .unwrap();
        assert_eq!((coverage.discovered_files, coverage.indexed_files), (1, 1));
        assert_eq!(coverage.tier, "tier_d");
        assert_ne!(coverage.status, "complete");
        let original = service
            .loaded_generation_snapshot(initial.generation)
            .unwrap();
        let identities = original
            .document()
            .entities
            .iter()
            .map(|entity| (entity.id, (entity.kind, entity.canonical_name.clone())))
            .collect::<BTreeMap<_, _>>();
        assert_eq!(identities.len(), 8);
        let noop = service
            .index_repository(fixture.path(), &deadline())
            .unwrap();
        assert_eq!(noop.generation, initial.generation);
        let changed = source.replace("SELECT value;", "SELECT value + 1;");
        fs::write(fixture.path().join("schema.sql"), &changed).unwrap();
        let updated = service
            .index_repository(fixture.path(), &deadline())
            .unwrap();
        assert_ne!(updated.generation, initial.generation);
        drop(original);
        drop(service);
        let restored = FirstSliceService::new_durable(3, paths.state_dir(), &deadline()).unwrap();
        for (receipt, expected_source) in [(&initial, source), (&updated, changed.as_str())] {
            let generation = restored
                .loaded_generation_snapshot(receipt.generation)
                .unwrap();
            let document = generation.document();
            assert_eq!(
                document
                    .entities
                    .iter()
                    .map(|entity| (entity.id, (entity.kind, entity.canonical_name.clone())))
                    .collect::<BTreeMap<_, _>>(),
                identities
            );
            for detail in [
                "sql-dialect-statement-coverage-incomplete",
                "sql-catalog-resolution-unavailable",
                "sql-function-body-semantics-unavailable",
            ] {
                assert!(
                    document
                        .skipped_regions
                        .iter()
                        .any(|gap| gap.detail == detail)
                );
            }
            let function = document
                .entities
                .iter()
                .find(|entity| entity.kind == EntityKind::Function)
                .unwrap();
            let explained = restored
                .symbol_explain(receipt.generation, function.id, &deadline())
                .unwrap();
            let signature = explained.data.signature.as_ref().unwrap();
            assert_eq!(
                signature.text(),
                "CREATE FUNCTION app.identity(value INT) RETURNS INT"
            );
            assert!(!signature.is_truncated());
            let file = document
                .files
                .iter()
                .find(|file| file.path == "schema.sql")
                .unwrap();
            let reference = file.evidence.source.clone().unwrap();
            assert_eq!(reference.generation(), receipt.generation);
            let read = restored
                .source_read(receipt.generation, vec![reference], &deadline())
                .unwrap();
            assert_eq!(read.data.chunks[0].bytes, expected_source.as_bytes());
            assert_eq!(read.data.chunks[0].language, "sql");
            for (name, kind, count) in [
                ("app.account", EntityKind::DatabaseObject, 2),
                ("app.active", EntityKind::DatabaseObject, 1),
                ("app.identity", EntityKind::Function, 1),
            ] {
                let located = restored
                    .code_locate(
                        receipt.generation,
                        name.to_owned(),
                        LocateMode::Exact,
                        10,
                        0,
                        &deadline(),
                    )
                    .unwrap();
                let symbols = located
                    .data
                    .hits
                    .iter()
                    .filter_map(|hit| hit.symbol)
                    .collect::<BTreeSet<_>>();
                assert_eq!(symbols.len(), count);
                for symbol in symbols {
                    let explained = restored
                        .symbol_explain(receipt.generation, symbol, &deadline())
                        .unwrap();
                    assert_eq!(explained.data.entity.kind, kind);
                    let reference = explained.data.entity.evidence.source.unwrap();
                    assert_eq!(reference.generation(), receipt.generation);
                    let start = usize::try_from(reference.span().start_byte()).unwrap();
                    let end = usize::try_from(reference.span().end_byte()).unwrap();
                    let read = restored
                        .source_read_with_options_and_budget(
                            receipt.generation,
                            vec![reference],
                            SourceReadOptions::new()
                                .with_context_lines_before(0)
                                .with_context_lines_after(0),
                            FirstSliceBudget::default(),
                            &deadline(),
                        )
                        .unwrap();
                    assert_eq!(
                        read.data.chunks[0].bytes,
                        expected_source.as_bytes()[start..end]
                    );
                }
            }
        }
    }

    #[test]
    fn r_parameter_candidates_keep_lexical_owners_after_incremental_restart() {
        let storage = durable_test_tempdir();
        let paths = RuntimePaths::new(storage.path().join("state"), storage.path().join("runtime"))
            .unwrap();
        paths.prepare_owner().unwrap();
        let fixture = durable_test_tempdir();
        let source = "apply_one <- function(callback, value) {\n  callback(value)\n  nested <- function(value) { callback(value) }\n  nested(value)\n}\nunrelated <- function(callback, value) { callback(value) }\n";
        fs::write(fixture.path().join("callbacks.R"), source).unwrap();
        let mut service =
            FirstSliceService::new_durable(3, paths.state_dir(), &deadline()).unwrap();
        let initial = service
            .index_repository(fixture.path(), &deadline())
            .unwrap();
        assert_eq!(initial.indexed_files, 1);
        assert_eq!(
            service
                .index_repository(fixture.path(), &deadline())
                .unwrap()
                .generation,
            initial.generation
        );
        let changed = source.replacen("callback(value)", "callback(value + 1)", 1);
        fs::write(fixture.path().join("callbacks.R"), &changed).unwrap();
        let updated = service
            .index_repository(fixture.path(), &deadline())
            .unwrap();
        assert_ne!(updated.generation, initial.generation);
        drop(service);
        let restored = FirstSliceService::new_durable(3, paths.state_dir(), &deadline()).unwrap();
        let mut previous_parameters = None;
        for (receipt, source) in [(&initial, source), (&updated, changed.as_str())] {
            let snapshot = restored
                .loaded_generation_snapshot(receipt.generation)
                .unwrap();
            let document = snapshot.document();
            let entities = document
                .entities
                .iter()
                .map(|entity| (entity.id, entity))
                .collect::<BTreeMap<_, _>>();
            let parameters = document
                .entities
                .iter()
                .filter(|entity| entity.canonical_name == "callback")
                .map(|entity| {
                    assert_eq!(entity.kind, rootlight_ir::EntityKind::Parameter);
                    let Some(rootlight_ir::ContainerRef::Entity(owner)) = entity.container else {
                        panic!("parameter owner")
                    };
                    (entities[&owner].canonical_name.as_str(), entity.id)
                })
                .collect::<BTreeMap<_, _>>();
            assert_eq!(parameters.len(), 2);
            if let Some(previous) = &previous_parameters {
                assert_eq!(&parameters.values().copied().collect::<Vec<_>>(), previous);
            }
            previous_parameters = Some(parameters.values().copied().collect::<Vec<_>>());
            let calls = document
                .occurrences
                .iter()
                .filter(|occurrence| {
                    occurrence.role == rootlight_ir::OccurrenceRole::CallSite
                        && occurrence.syntactic_text_hash == content_hash(b"callback")
                })
                .collect::<Vec<_>>();
            assert_eq!(calls.len(), 3);
            for call in calls {
                let enclosing = entities[&call.enclosing.unwrap()].canonical_name.as_str();
                let owner = match enclosing {
                    "apply_one" | "nested" => "apply_one",
                    "unrelated" => "unrelated",
                    _ => panic!("unexpected callback scope: {enclosing}"),
                };
                let target = parameters[owner];
                assert!(
                    matches!(&call.target,
                    rootlight_ir::OccurrenceTarget::Candidates { symbols, total_count: 1, completeness: rootlight_ir::CoverageStatus::Complete, .. }
                        if symbols == &[target]),
                    "{:?}",
                    call.target
                );
                let dispatch = document
                    .relations
                    .iter()
                    .filter(|relation| {
                        relation.subject == rootlight_ir::RelationEndpoint::Occurrence(call.id)
                            && relation.predicate
                                == rootlight_ir::RelationPredicate::DispatchCandidate
                    })
                    .collect::<Vec<_>>();
                assert_eq!(dispatch.len(), 1);
                assert_eq!(
                    dispatch[0].object,
                    rootlight_ir::RelationEndpoint::Entity(target)
                );
                assert!(!document.relations.iter().any(|relation| {
                    relation.subject == rootlight_ir::RelationEndpoint::Occurrence(call.id)
                        && relation.predicate == rootlight_ir::RelationPredicate::Calls
                }));
                let read = restored
                    .source_read_with_options_and_budget(
                        receipt.generation,
                        vec![call.source.clone()],
                        SourceReadOptions::new()
                            .with_context_lines_before(0)
                            .with_context_lines_after(0),
                        FirstSliceBudget::default(),
                        &deadline(),
                    )
                    .unwrap();
                let span = call.source.span();
                assert_eq!(
                    read.data.chunks[0].bytes,
                    source
                        .as_bytes()
                        .get(
                            usize::try_from(span.start_byte()).unwrap()
                                ..usize::try_from(span.end_byte()).unwrap()
                        )
                        .unwrap()
                );
            }
            let values = document
                .entities
                .iter()
                .filter(|entity| entity.canonical_name == "value")
                .map(|entity| {
                    let Some(rootlight_ir::ContainerRef::Entity(owner)) = entity.container else {
                        panic!("value owner")
                    };
                    (entities[&owner].canonical_name.as_str(), entity.id)
                })
                .collect::<BTreeMap<_, _>>();
            assert_eq!(values.len(), 3);
            let references = document
                .occurrences
                .iter()
                .filter(|occurrence| {
                    occurrence.role == rootlight_ir::OccurrenceRole::Reference
                        && occurrence.syntactic_text_hash == content_hash(b"value")
                })
                .collect::<Vec<_>>();
            assert_eq!(references.len(), 4);
            for reference in references {
                let enclosing = entities[&reference.enclosing.unwrap()]
                    .canonical_name
                    .as_str();
                // Retain ancestor candidates: source scopes alone do not prove runtime shadowing.
                let mut expected = match enclosing {
                    "apply_one" => vec![values["apply_one"]],
                    "nested" => vec![values["apply_one"], values["nested"]],
                    "unrelated" => vec![values["unrelated"]],
                    _ => panic!("unexpected value scope: {enclosing}"),
                };
                expected.sort_unstable();
                let rootlight_ir::OccurrenceTarget::Candidates {
                    symbols,
                    total_count,
                    completeness,
                    ..
                } = &reference.target
                else {
                    panic!("parameter candidates")
                };
                assert_eq!(symbols, &expected);
                assert_eq!(*total_count, u64::try_from(expected.len()).unwrap());
                assert_eq!(*completeness, rootlight_ir::CoverageStatus::Complete);
            }
            assert!(
                document
                    .skipped_regions
                    .iter()
                    .any(|gap| gap.detail == "r-environment-dispatch-resolution-unavailable")
            );
        }
    }

    #[test]
    fn r_call_targets_preserve_candidates_and_qualified_uncertainty_after_restart() {
        let storage = durable_test_tempdir();
        let paths = RuntimePaths::new(storage.path().join("state"), storage.path().join("runtime"))
            .unwrap();
        paths.prepare_owner().unwrap();
        let fixture = durable_test_tempdir();
        let source = "target <- function(value) { value }\n`target`(1)\n\"target\"(2)\npkg::target(3)\nobject$target(4)\ntarget()(5)\n\"\\xff\"(6)\n";
        fs::write(fixture.path().join("calls.R"), source).unwrap();
        let mut service =
            FirstSliceService::new_durable(3, paths.state_dir(), &deadline()).unwrap();
        let initial = service
            .index_repository(fixture.path(), &deadline())
            .unwrap();
        assert_eq!(initial.indexed_files, 1);
        let noop = service
            .index_repository(fixture.path(), &deadline())
            .unwrap();
        assert_eq!(noop.generation, initial.generation);
        let changed = source.replace("{ value }", "{ value + 1 }");
        fs::write(fixture.path().join("calls.R"), &changed).unwrap();
        let updated = service
            .index_repository(fixture.path(), &deadline())
            .unwrap();
        assert_ne!(updated.generation, initial.generation);
        drop(service);
        let restored = FirstSliceService::new_durable(3, paths.state_dir(), &deadline()).unwrap();
        let mut target_id = None;
        for (receipt, source) in [(&initial, source), (&updated, changed.as_str())] {
            let snapshot = restored
                .loaded_generation_snapshot(receipt.generation)
                .unwrap();
            let document = snapshot.document();
            let target = document
                .entities
                .iter()
                .find(|entity| entity.canonical_name == "target")
                .unwrap();
            if let Some(previous) = target_id {
                assert_eq!(target.id, previous);
            }
            target_id = Some(target.id);
            let calls: Vec<_> = document
                .occurrences
                .iter()
                .filter(|occurrence| occurrence.role == rootlight_ir::OccurrenceRole::CallSite)
                .collect();
            assert_eq!(calls.len(), 7);
            for call in calls {
                let span = call.source.span();
                let written = source
                    .get(
                        usize::try_from(span.start_byte()).unwrap()
                            ..usize::try_from(span.end_byte()).unwrap(),
                    )
                    .unwrap();
                if ["`target`(1)", "\"target\"(2)", "target()"].contains(&written) {
                    let rootlight_ir::OccurrenceTarget::Candidates {
                        symbols,
                        total_count,
                        completeness,
                        ..
                    } = &call.target
                    else {
                        panic!(
                            "expected a source-backed candidate, not a runtime guarantee: {written}: {:?}",
                            call.target
                        );
                    };
                    assert_eq!(symbols, &[target.id]);
                    assert_eq!(*total_count, 1);
                    assert_eq!(*completeness, rootlight_ir::CoverageStatus::Complete);
                } else {
                    let (syntax, detail) = match written {
                        "pkg::target(3)" => (
                            "r.namespace_call.call",
                            "r-package-namespace-target-unavailable",
                        ),
                        "object$target(4)" => {
                            ("r.member_call.call", "r-object-member-target-unavailable")
                        }
                        "target()(5)" => {
                            ("r.computed_call.call", "r-computed-call-target-unavailable")
                        }
                        "\"\\xff\"(6)" => {
                            ("r.unavailable_name.call", "r-reference-name-unavailable")
                        }
                        _ => panic!("unexpected call: {written}"),
                    };
                    assert_eq!(call.syntax_kind, syntax);
                    assert!(matches!(
                        call.target,
                        rootlight_ir::OccurrenceTarget::Unresolved { .. }
                    ));
                    assert!(document.skipped_regions.iter().any(|gap| {
                        gap.detail == detail
                            && gap
                                .evidence
                                .source
                                .as_ref()
                                .is_some_and(|reference| reference.span() == span)
                    }));
                }
                let read = restored
                    .source_read_with_options_and_budget(
                        receipt.generation,
                        vec![call.source.clone()],
                        SourceReadOptions::new()
                            .with_context_lines_before(0)
                            .with_context_lines_after(0),
                        FirstSliceBudget::default(),
                        &deadline(),
                    )
                    .unwrap();
                assert_eq!(read.data.chunks[0].bytes, written.as_bytes());
            }
        }
    }

    #[test]
    fn r_source_occurrences_survive_incremental_publication_and_restart() {
        let storage = durable_test_tempdir();
        let paths = RuntimePaths::new(storage.path().join("state"), storage.path().join("runtime"))
            .unwrap();
        paths.prepare_owner().unwrap();
        let fixture = durable_test_tempdir();
        let source = "`identity` <- function(value) { value }\n\"\\u0069dentity\" <- function(value) { value + 1 }\nlapply(values, function(value) { value })\n";
        fs::write(fixture.path().join("analysis.R"), source).unwrap();
        let mut service =
            FirstSliceService::new_durable(3, paths.state_dir(), &deadline()).unwrap();
        let initial = service
            .index_repository(fixture.path(), &deadline())
            .unwrap();
        assert_eq!(initial.indexed_files, 1);
        let status = service.repository_status(initial.repository, None).unwrap();
        let coverage = status
            .coverage
            .iter()
            .find(|row| row.language == "r")
            .unwrap();
        assert_eq!((coverage.discovered_files, coverage.indexed_files), (1, 1));
        assert_eq!(coverage.tier, "tier_d");
        assert_ne!(coverage.status, "complete");
        let original = service
            .loaded_generation_snapshot(initial.generation)
            .unwrap();
        let identities = original
            .document()
            .entities
            .iter()
            .map(|entity| {
                (
                    entity.id,
                    (entity.kind, entity.canonical_name.clone(), entity.container),
                )
            })
            .collect::<BTreeMap<_, _>>();
        assert_eq!(identities.len(), 7);
        let noop = service
            .index_repository(fixture.path(), &deadline())
            .unwrap();
        assert_eq!(noop.generation, initial.generation);
        let changed = source.replace("{ value }", "{ value * 2 }");
        fs::write(fixture.path().join("analysis.R"), &changed).unwrap();
        let updated = service
            .index_repository(fixture.path(), &deadline())
            .unwrap();
        assert_ne!(updated.generation, initial.generation);
        drop(original);
        drop(service);
        let restored = FirstSliceService::new_durable(3, paths.state_dir(), &deadline()).unwrap();
        for (receipt, expected_source) in [(&initial, source), (&updated, changed.as_str())] {
            let generation = restored
                .loaded_generation_snapshot(receipt.generation)
                .unwrap();
            let document = generation.document();
            assert_eq!(
                document
                    .entities
                    .iter()
                    .map(|entity| (
                        entity.id,
                        (entity.kind, entity.canonical_name.clone(), entity.container)
                    ))
                    .collect::<BTreeMap<_, _>>(),
                identities
            );
            for detail in [
                "r-runtime-generated-definitions-unavailable",
                "r-environment-dispatch-resolution-unavailable",
            ] {
                assert!(
                    document
                        .skipped_regions
                        .iter()
                        .any(|gap| gap.detail == detail)
                );
            }
            let file = document
                .files
                .iter()
                .find(|file| file.path == "analysis.R")
                .unwrap();
            let reference = file.evidence.source.clone().unwrap();
            assert_eq!(reference.generation(), receipt.generation);
            let read = restored
                .source_read(receipt.generation, vec![reference], &deadline())
                .unwrap();
            assert_eq!(read.data.chunks[0].bytes, expected_source.as_bytes());
            assert_eq!(read.data.chunks[0].language, "r");
            for (name, kind, count) in [
                ("identity", EntityKind::Function, 2),
                ("<anonymous>", EntityKind::Function, 1),
                ("value", EntityKind::Parameter, 3),
            ] {
                let located = restored
                    .code_locate(
                        receipt.generation,
                        name.to_owned(),
                        LocateMode::Exact,
                        10,
                        0,
                        &deadline(),
                    )
                    .unwrap();
                let symbols = located
                    .data
                    .hits
                    .iter()
                    .filter_map(|hit| hit.symbol)
                    .collect::<BTreeSet<_>>();
                assert_eq!(symbols.len(), count);
                for symbol in symbols {
                    let explained = restored
                        .symbol_explain(receipt.generation, symbol, &deadline())
                        .unwrap();
                    assert_eq!(explained.data.entity.kind, kind);
                    if kind == EntityKind::Function {
                        let signature = explained.data.signature.as_ref().unwrap();
                        assert_eq!(signature.text(), "function(value)");
                        assert!(!signature.is_truncated());
                    }
                    let reference = explained.data.entity.evidence.source.unwrap();
                    assert_eq!(reference.generation(), receipt.generation);
                    let start = usize::try_from(reference.span().start_byte()).unwrap();
                    let end = usize::try_from(reference.span().end_byte()).unwrap();
                    let read = restored
                        .source_read_with_options_and_budget(
                            receipt.generation,
                            vec![reference],
                            SourceReadOptions::new()
                                .with_context_lines_before(0)
                                .with_context_lines_after(0),
                            FirstSliceBudget::default(),
                            &deadline(),
                        )
                        .unwrap();
                    assert_eq!(
                        read.data.chunks[0].bytes,
                        expected_source.as_bytes()[start..end]
                    );
                }
            }
        }
    }

