    #[test]
    fn global_text_finds_tail_terms_across_source_chunks_after_restart() {
        assert_global_source_terms(false);
    }

    #[test]
    fn file_only_global_text_finds_tail_terms_after_restart() {
        assert_global_source_terms(true);
    }

    fn assert_global_source_terms(file_only: bool) {
        let storage = durable_test_tempdir();
        let paths = RuntimePaths::new(storage.path().join("state"), storage.path().join("runtime"))
            .expect("runtime paths");
        paths.prepare_owner().expect("private paths");
        let fixture = durable_test_tempdir();
        let source = format!(
            "// headmarker\n// {}\n// tailmarker\n",
            "padding ".repeat(12_000)
        );
        fs::write(fixture.path().join("source.rs"), &source).expect("Rust source writes");
        fs::write(
            fixture.path().join("config.yaml"),
            source.replace("//", "#"),
        )
        .expect("unparsed source writes");
        let mut service = FirstSliceService::new_durable(2, paths.state_dir(), &deadline())
            .expect("service initializes");
        if file_only {
            let mut ir = service.analysis_limits.ir().clone();
            ir.max_files = 1;
            replace_service_ir_limits(&mut service, ir);
        }
        let receipt = service
            .index_repository(fixture.path(), &deadline())
            .expect("sources publish");
        if file_only {
            let generation = service
                .loaded_generation_snapshot(receipt.generation)
                .expect("snapshot retained");
            assert!(!generation.source_files().is_empty());
        }
        for restored in [false, true] {
            if restored {
                drop(service);
                service = FirstSliceService::new_durable(2, paths.state_dir(), &deadline())
                    .expect("durable source index restores");
            }
            for query in ["tailmarker", "headmarker tailmarker"] {
                let located = service
                    .code_locate(
                        receipt.generation,
                        query.to_owned(),
                        LocateMode::Text,
                        10,
                        0,
                        &deadline(),
                    )
                    .expect("global text query executes");
                let files = located
                    .data
                    .hits
                    .iter()
                    .filter(|hit| hit.symbol.is_none())
                    .map(|hit| hit.path.as_str())
                    .collect::<BTreeSet<_>>();
                assert_eq!(
                    files,
                    BTreeSet::from(["source.rs", "config.yaml"]),
                    "restored={restored}, query={query}"
                );
                assert!(!located.data.truncated);
                for hit in located.data.hits.iter().filter(|hit| hit.symbol.is_none()) {
                    let reference = hit.source.clone().expect("file source identity");
                    assert_eq!(reference.generation(), receipt.generation);
                    let expected = if hit.path == "source.rs" {
                        source.clone()
                    } else {
                        source.replace("//", "#")
                    };
                    assert_eq!(reference.content_hash(), content_hash(expected.as_bytes()));
                    let coverage = service
                        .source_file_lexical_coverage_until(
                            receipt.generation,
                            reference.span().file(),
                            &deadline(),
                        )
                        .expect("lexical accounting resolves")
                        .expect("full-source accounting retained");
                    assert_eq!(
                        coverage.source_bytes,
                        u64::try_from(expected.len()).expect("source length")
                    );
                    assert_eq!(coverage.omitted_word_bytes, 0);
                    assert_eq!(coverage.omitted_words, 0);
                    assert!(coverage.is_complete());
                    let mut bytes = Vec::new();
                    for start in (0..expected.len()).step_by(16 * 1024) {
                        let end = (start + 16 * 1024).min(expected.len());
                        let span = SourceSpan::new(
                            reference.span().file(),
                            u64::try_from(start).expect("fixture offset"),
                            u64::try_from(end).expect("fixture offset"),
                        )
                        .expect("bounded source span");
                        let part = SourceRef::new(
                            reference.repository(),
                            reference.generation(),
                            span,
                            reference.content_hash(),
                            None,
                        );
                        let read = service
                            .source_read_with_options_and_budget(
                                receipt.generation,
                                vec![part],
                                SourceReadOptions::new()
                                    .with_context_lines_before(0)
                                    .with_context_lines_after(0),
                                FirstSliceBudget::default(),
                                &deadline(),
                            )
                            .expect("source reads in bounded requests");
                        bytes.extend_from_slice(&read.data.chunks[0].bytes);
                    }
                    assert_eq!(bytes, expected.as_bytes());
                }
            }
        }
    }

    #[test]
    fn scoped_text_retrieves_source_after_projection_prefix() {
        let storage = durable_test_tempdir();
        let paths = RuntimePaths::new(storage.path().join("state"), storage.path().join("runtime"))
            .expect("test runtime paths are valid");
        paths
            .prepare_owner()
            .expect("private runtime paths prepare");
        let fixture = TempDir::new().expect("fixture root exists");
        let source = format!(
            "/* {} */\n.tailOnlyMarker {{ color: green; }}\n",
            " ".repeat(SOURCE_FALLBACK_TEXT_BYTES + 257)
        );
        fs::write(fixture.path().join("theme.css"), &source).expect("source writes");
        let mut service = FirstSliceService::new_durable(2, paths.state_dir(), &deadline())
            .expect("durable service initializes");
        let receipt = service
            .index_repository(fixture.path(), &deadline())
            .expect("source fixture publishes");
        for restored in [false, true] {
            if restored {
                drop(service);
                service = FirstSliceService::new_durable(2, paths.state_dir(), &deadline())
                    .expect("durable source restores");
            }
            let gaps = service
                .coverage_gaps_until(receipt.repository, receipt.generation, &deadline())
                .expect("supported source projection gaps resolve");
            assert!(!gaps.iter().any(|gap| {
                gap.reason == FirstSliceCoverageGapReason::Truncated
                    && gap.language.as_deref() == Some("css")
                    && gap.files == 1
            }));
            for (query, expected) in [("tailOnlyMarker", true), ("absentMarker", false)] {
                let located = service
                    .code_locate_with_filters_and_budget(
                        receipt.generation,
                        query.to_owned(),
                        LocateMode::Text,
                        Vec::new(),
                        vec!["theme.css".to_owned()],
                        8,
                        0,
                        FirstSliceBudget::default(),
                        &deadline(),
                    )
                    .expect("exact source scope executes");
                let hit = located.data.hits.iter().find(|hit| hit.symbol.is_none());
                assert_eq!(
                    hit.is_some(),
                    expected,
                    "restored={restored}, query={query}"
                );
                if let Some(hit) = hit {
                    let read = service
                        .source_read(
                            receipt.generation,
                            vec![hit.source.clone().expect("file hit has source evidence")],
                            &deadline(),
                        )
                        .expect("full generation-bound source remains readable");
                    assert_eq!(read.data.chunks[0].bytes, source.as_bytes());
                }
            }
            assert!(matches!(
                service.code_locate_with_filters_and_budget(
                    receipt.generation,
                    "tailOnlyMarker".to_owned(),
                    LocateMode::Text,
                    Vec::new(),
                    vec!["theme.css".to_owned()],
                    8,
                    0,
                    FirstSliceBudget::default().reduce_max_duration(Duration::from_nanos(1)),
                    &deadline(),
                ),
                Err(FirstSliceError::Cancelled(
                    CancellationReason::DeadlineExceeded
                ))
            ));
        }
    }

